{"code": "def authorize(request: dict, policies: list[dict]) -> str:
    """
    Decide access requests against the policy set using XACML 3.0 deny-overrides.

    Returns "ALLOW" or "DENY".
    """
    # Validate request
    required_request_fields = {"subject", "roles", "action", "resource"}
    for field in required_request_fields:
        if field not in request:
            raise ValueError(f"Request missing required field: {field}")

    if not isinstance(request["roles"], list):
        raise ValueError("roles must be a list")

    # Validate all policies before deciding
    required_policy_fields = {"effect", "principal", "action", "resource"}
    for policy in policies:
        for field in required_policy_fields:
            if field not in policy:
                raise ValueError(f"Policy missing required field: {field}")

        if policy["effect"] not in ("ALLOW", "DENY"):
            raise ValueError(f"Invalid effect: {policy['effect']!r}")

    # Check for matching policies using deny-overrides algorithm
    has_allow = False

    for policy in policies:
        if _matches_policy(request, policy):
            if policy["effect"] == "DENY":
                return "DENY"
            elif policy["effect"] == "ALLOW":
                has_allow = True

    if has_allow:
        return "ALLOW"
    else:
        return "DENY"


def _matches_policy(request: dict, policy: dict) -> bool:
    """Check if a request matches a policy."""
    return (
        _matches_principal(request, policy["principal"])
        and _matches_pattern(request["action"], policy["action"])
        and _matches_pattern(request["resource"], policy["resource"])
    )


def _matches_principal(request: dict, principal: str) -> bool:
    """Check if the principal matches the request."""
    if principal == "*":
        return True

    if principal.startswith("user:"):
        user_part = principal[5:]
        return user_part == request["subject"]

    if principal.startswith("role:"):
        role_part = principal[5:]
        return role_part in request["roles"]

    return False


def _matches_pattern(value: str, pattern: str) -> bool:
    """Check if a value matches a pattern (with trailing * as prefix)."""
    if pattern == "*":
        return True

    if pattern.endswith("*"):
        prefix = pattern[:-1]
        return value.startswith(prefix)

    return value == pattern
